import logging
import time

from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector
from taf.sw.dcap.rd.facade import DcapConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class DcapTraceCollector(Using("local_executor"), StartableCollector):
    """
    DCAP trace collector.
    """

    def __init__(
            self,
            dcap,
            trace,
            invalidate_bts_info_cache=False,
            ssh_forwarding_branch=None,
            **kwargs):
        super(DcapTraceCollector, self).__init__(**kwargs)

        self._dcap = dcap.copy()
        self._trace = trace.copy()
        self._invalidate_bts_info_cache = invalidate_bts_info_cache
        for key, value in {"wait_for_activation": True}.items():
            self._trace.setdefault(key, value)

        self._dcap_connection = None
        self._trace_id = None
        self._trace_id_list = []

        self._ssh_forwarding_branch = ssh_forwarding_branch
        if ssh_forwarding_branch is not None:
            self.add_prerequisite(ssh_forwarding_branch)

    @property
    def dcap(self):
        return self._dcap

    @property
    def trace(self):
        return self._trace

    @property
    def ssh_forwarding_branch(self):
        return self._ssh_forwarding_branch

    def _setup(self):
        if self._ssh_forwarding_branch is not None:
            self._dcap["host"] = "127.0.0.1"
            self._dcap["port"] = self._ssh_forwarding_branch.forwarding_port
        self._dcap_connection = self._create_dcap_connection(**self._dcap)
        precondition_result = self._dcap_connection.check_precondition(self._invalidate_bts_info_cache, **self._trace)

        if not precondition_result.ok:
            error_msgs = precondition_result.msgs
            raise RuntimeError(f"Precondition check failed: {error_msgs}")

    def _create_dcap_connection(self, **kwargs):
        return DcapConnection(**kwargs)

    def _start(self):
        logging.debug("start DCAP trace, dcap=%r, trace=%r", self._dcap, self._trace)
        self._trace_id = self._dcap_connection.start_trace(**self._trace).tracer_id
        self._trace_id_list.append(self._trace_id)

    def _stop(self):
        logging.debug("stop DCAP trace, dcap=%r, trace=%r", self._dcap, self._trace)
        self._dcap_connection.stop_trace(trace_id=self._trace_id)
        self._check_trace_status_transition()

    def _collect(self, target_dir):
        result_path = self._dcap_connection.get_results(target_dir=target_dir)
        command = "mv '{result_path}' '{target_dir}/dcap.zip'".format(
            result_path=result_path,
            target_dir=target_dir
        )
        self._local_executor.execute(command)

    def _teardown(self):
        if self._trace_id_list:
            for trace_id in self._trace_id_list:
                try:
                    self._dcap_connection.delete_trace(trace_id=trace_id)
                except Exception as e:
                    logger.warning('delete_trace failed with: {}'.format(e))
        self._dcap_connection = None

    def _check_trace_status_transition(self):
        trace_data = self._dcap_connection.get_trace_info_by_id(trace_id=self._trace_id)
        last_status = trace_data.status
        logging.debug(last_status)
        while last_status in ['running', 'runningWithWarnings', 'stopping']:
            time.sleep(0.1)
            status = self._dcap_connection.get_trace_info_by_id(trace_id=self._trace_id).status
            if status != last_status:
                logging.debug(status)
                last_status = status
        if last_status not in ['ready', 'packaging', 'postProcessing']:
            raise RuntimeError(last_status + " is not expected status. Trace stop failed")
